// ---------------------------------------------------- KDA under 1 vs N threads --------
//
// The recurrence is parallelised over heads (k3_ops.c:869-873, mirrored in ops::kda_layer)
// and the C claims the result is bit-identical to the serial form, "gated by test_ops'
// kda fixtures under 1 vs N threads". The fixture above gates against the torch reference
// inside a tolerance; this gates the two thread counts against EACH OTHER, bitwise.
//
// The distinction matters here more than in the matmuls. Each head carries its own
// recurrent state across the sequence, so a head that read a neighbour's state, or a
// scatter that mixed two heads' outputs, would still produce a bounded, plausible,
// evolving stream -- the failure mode this codebase exists to catch. Both `out` and the
// recurrent state are compared, because a wrong state is invisible in one step's output
// and diverges over the next few.
fn kda_layer_in_pool(name: &str, threads: usize) -> (Vec<f32>, Vec<f32>) {
    let v = load(name);
    let d = k3::ops::KdaDims {
        hidden: shape(&v, "in")[2],
        heads: i(&v, "H"),
        head_dim: i(&v, "d_k"),
        conv_k: i(&v, "conv_k"),
        gate_lb: f(&v, "lower_bound"),
        rms_eps: f(&v, "rms_eps"),
    };
    let t: Vec<Vec<f32>> = [
        "q_proj", "k_proj", "v_proj", "g_proj", "o_proj", "f_a", "f_b", "b_proj", "q_conv",
        "k_conv", "v_conv", "A_log", "dt_bias", "o_norm",
    ]
    .iter()
    .map(|k| ten(&v, k))
    .collect();
    let w = k3::ops::KdaW {
        q: k3::ops::W::F32(&t[0]),
        k: k3::ops::W::F32(&t[1]),
        v: k3::ops::W::F32(&t[2]),
        g: k3::ops::W::F32(&t[3]),
        o: k3::ops::W::F32(&t[4]),
        f_a: k3::ops::W::F32(&t[5]),
        f_b: k3::ops::W::F32(&t[6]),
        b: k3::ops::W::F32(&t[7]),
        q_conv: &t[8],
        k_conv: &t[9],
        v_conv: &t[10],
        a_log: &t[11],
        dt_bias: &t[12],
        o_norm: &t[13],
    };
    let x = ten(&v, "in");
    let t_len = x.len() / d.hidden;
    rayon::ThreadPoolBuilder::new()
        .num_threads(threads)
        .build()
        .unwrap()
        .install(|| {
            let mut state = vec![0f32; k3::ops::kda_state_len(&d)];
            let mut got = vec![0f32; t_len * d.hidden];
            k3::ops::kda_layer(&mut got, &x, &w, &d, t_len, &mut state);
            (got, state)
        })
}

fn kda_thread_independence(name: &str) {
    let (out1, st1) = kda_layer_in_pool(name, 1);
    let (out8, st8) = kda_layer_in_pool(name, 8);
    for (i, (&a, &b)) in out1.iter().zip(&out8).enumerate() {
        assert_eq!(a.to_bits(), b.to_bits(), "{name}: out[{i}] moved with the thread count");
    }
    for (i, (&a, &b)) in st1.iter().zip(&st8).enumerate() {
        assert_eq!(a.to_bits(), b.to_bits(), "{name}: state[{i}] moved with the thread count");
    }
}

#[test]
fn kda_layer_single_token_is_independent_of_thread_count() {
    kda_thread_independence("kda_layer1");
}

// Eight tokens is the case that matters: with one token every head's recurrence is a
// single step and a state-sharing bug has nowhere to show.
#[test]
fn kda_layer_eight_tokens_is_independent_of_thread_count() {
    kda_thread_independence("kda_layer8");
}
